mapper.select:
select setmeal.id, category_id, setmeal.name, price, setmeal.status, description, image,
       category.name as category_name from setmeal,category

    category_id = category.id

        and category_id = #{categoryId}


        and setmeal.name like concat('%',#{name},'%')


        and setmeal.status = #{status}
